const now = Date.now();
let st = flow.get('sim') || {boxes: [], last: now, lastWrite: 0, lastWord: -1, spawnAt: 0, chute: 0, exited: 0};
const plc = flow.get('plc') || {status: 0, total: 0, small: 0, tall: 0};
const sw = flow.get('sw') || {};
const pulses = flow.get('pulses') || {start: 0, stop: 0, reset: 0};

const dt = Math.min((now - st.last) / 1000, 0.5);
st.last = now;

const motor   = (plc.status & 1) !== 0;
const divCmd  = (plc.status & 2) !== 0;
const jam     = (plc.status & 4) !== 0;
const divFail = (plc.status & 8) !== 0;

const SPEED = 100;      // px per second
const W = 30;           // box width in px
const ZONE_A = 100, ZONE_B = 120;   // sensor S1/S2 zone
const DIV_A = 300, DIV_B = 450;     // diverter zone
const EXIT_A = 560, EXIT_B = 580;   // exit sensor zone
const END = 600;

// move boxes only while the PLC runs the motor
if (motor) {
    st.boxes.forEach(b => { b.x += SPEED * dt; });
}

// diverter: extended while the PLC commands it (unless the stuck switch is on)
const extended = divCmd && !sw.stuck;
if (extended) {
    const keep = [];
    st.boxes.forEach(b => {
        if (b.tall && b.x + W > DIV_A && b.x < DIV_B) { st.chute++; }
        else { keep.push(b); }
    });
    st.boxes = keep;
}

// boxes leaving the end of the belt
const remain = [];
st.boxes.forEach(b => { if (b.x >= END) { st.exited++; } else { remain.push(b); } });
st.boxes = remain;

// spawning (one box on the belt at a time)
if (st.boxes.length === 0) {
    if (st.spawnAt === 0) { st.spawnAt = now + 3000; }
    if (motor && (sw.spawn || (sw.auto === true && now >= st.spawnAt))) {
        st.boxes.push({x: 0, tall: Math.random() < 0.4});
        st.spawnAt = 0;
        sw.spawn = false;
    }
} else {
    sw.spawn = false;
}
flow.set('sw', sw);

// sensors
const overlap = b => (b.x < ZONE_B && b.x + W > ZONE_A);
const s1 = sw.block === true || st.boxes.some(overlap);
const s2 = st.boxes.some(b => b.tall && overlap(b));
const sExit = st.boxes.some(b => b.x < EXIT_B && b.x + W > EXIT_A);

// build the input word for the PLC (holding register 0)
const word = (s1 ? 1 : 0) | (s2 ? 2 : 0) | (sExit ? 4 : 0) | (extended ? 8 : 0)
           | (sw.estop === true ? 0 : 16)
           | (now < pulses.start ? 32 : 0)
           | (now < pulses.stop ? 64 : 0)
           | (now < pulses.reset ? 128 : 0);

flow.set('sim', st);

let toPlc = null;
if (word !== st.lastWord || now - st.lastWrite > 1000) {
    st.lastWord = word;
    st.lastWrite = now;
    toPlc = {payload: word};
}

const view = {
    payload: {
        boxes: st.boxes.map(b => ({x: Math.round(b.x), tall: b.tall})),
        s1: s1, s2: s2, sExit: sExit, ext: extended,
        motor: motor, jam: jam, divFail: divFail, estop: sw.estop === true,
        total: plc.total, small: plc.small, tall: plc.tall,
        chute: st.chute, exited: st.exited
    }
};
return [toPlc, view];

if (!Array.isArray(msg.payload) || msg.payload.length < 4) { return null; }
flow.set('plc', {
    status: msg.payload[0],
    total: msg.payload[1],
    small: msg.payload[2],
    tall: msg.payload[3]
});
return null;

const now = Date.now();
const t = msg.topic;
if (t === 'start' || t === 'stop' || t === 'reset') {
    const p = flow.get('pulses') || {start: 0, stop: 0, reset: 0};
    p[t] = now + 400;
    flow.set('pulses', p);
} else if (t === 'spawn') {
    const s = flow.get('sw') || {};
    s.spawn = true;
    flow.set('sw', s);
} else {
    const s = flow.get('sw') || {};
    s[t] = msg.payload;
    flow.set('sw', s);
}
return null;
